+        sizeof(uint32_t),
+        sizeof(uint32_t),
+        sizeof(uint32_t),
+        sizeof(CheckValue),
+        sizeof(CheckNodeConversions),
+    };
+    uint8_t* memory[15] = { 0 };
+    uint64_t lengths[15] = { 0 };
